import{readFile,writeFile}from'node:fs/promises';import{createHash}from'node:crypto';import{createPostgresConnection,HostedWorkspaceDatabase}from'../../packages/neuvetra-database/src/index';import{createM78Routes}from'../../apps/site-api/src/workspace/m78-routes';import{decodeScope1Register,decodeScope1Report}from'../../apps/site-web/src/lib/m78-api';import{m78FixtureAuthorities}from'../../tools/staging/m78-backend-fixture';import{M78_REVIEWED_POLICY}from'../../packages/neuvetra-database/src/m78-policy';
const sha=(x:string|Uint8Array)=>createHash('sha256').update(x).digest('hex'),c=(v:any):string=>v===null||typeof v!=='object'?JSON.stringify(v):Array.isArray(v)?'['+v.map(c).join(',')+']':'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+c(v[k])).join(',')+'}',check=(x:unknown,m:string)=>{if(!x)throw Error(m)};
const jp='.superpowers/m78-continuation-native-20260922-run.jsonl',bytes=await readFile(jp);check(sha(bytes)===process.argv[2],'Journal changed');const events=bytes.toString().trim().split('\n').map(x=>JSON.parse(x));let prev=null;for(let i=0;i<events.length;i++){const{sha256,...body}=events[i];check(body.sequence===i+1&&body.previousSha256===prev&&sha(c(body))===sha256,'Hash chain');prev=sha256}check(events.length===113&&prev===process.argv[3]&&events.at(-1).kind==='complete','Complete exact journal');for(let n=0;n<37;n++){const[a,b,d]=events.slice(1+n*3,4+n*3);check(a.kind==='post_intent'&&b.kind==='post_outcome'&&d.kind==='post_verified'&&a.data.name===b.data.name&&b.data.name===d.data.name&&b.data.status===201&&b.data.responseSha256===d.data.responseSha256,'Intent outcome verification chain')}
check(events[1].data.name==='m78_initial_unreviewed_report'&&!events.some(e=>e.kind==='post_intent'&&(e.data.name==='m78_initial_blocked_inventory'||e.data.name.endsWith('_write_refused'))),'Forbidden original operation replay');
const baseline=events[0].data,terminal=events.at(-1).data,input=baseline.input,ip='.superpowers/m78-continuation-native-20260922-input.json';check(sha(await readFile(ip))==='e76f74d0a1bb61b08b87fc9959ecd5244be27f4c4d8314e7ddd1d5d7d40e17fc'&&c(JSON.parse(await readFile(ip,'utf8')))===c(input),'Input pin');for(const pin of[...input.provenancePins,...input.reviewedSourcePins])check(sha(await readFile(pin.path))===pin.sha256,'Changed provenance/source '+pin.path);check(input.reviewedSourcePins.length===122,'122pins');
const name='m78_ops_continuation_20260922',company=input.companyId,user=input.actorIds.member,admin=createPostgresConnection('postgres://supabase_admin@127.0.0.1:55472/'+name,{tls:false,maxConnections:1}),runtime=createPostgresConnection('postgres://neuvetra_runtime@127.0.0.1:55472/'+name,{tls:false,maxConnections:1});
async function rows(){return admin.transaction(async tx=>{await tx.exec('set transaction isolation level repeatable read read only');const out:Record<string,string[]>={};for(const{name}of(await tx.query<{name:string}>("select table_name name from information_schema.tables where table_schema='neuvetra' and table_type='BASE TABLE' order by table_name")).rows){check(/^[a-z0-9_]+$/.test(name),'Unsafe table');out[name]=(await tx.query<{row:string}>(`select neuvetra.m67_canonical(to_jsonb(t))row from neuvetra.${name} t order by neuvetra.m67_canonical(to_jsonb(t)) collate "C"`)).rows.map(r=>r.row)}return out})}
try{await admin.exec('set default_transaction_read_only=on');const before=await rows();check(sha(c(before))===terminal.finalRowsSha256,'Current rows differ from completed recipe');const old=baseline.oldRows,heads=new Set(['corporate_inventory','stationary_gas','mobile_diesel','controlled_fleet','stationary_diesel','stationary_equipment','fugitive','scope1'].map(x=>x+'_heads'));let retained=0;for(const table of Object.keys(old)){const norm=(row:string)=>{const v=JSON.parse(row);if(heads.has(table)&&v.company_id===company){delete v.version_id;delete v.revision}return c(v)},counts=new Map<string,number>();for(const row of before[table]!){const key=norm(row);counts.set(key,(counts.get(key)??0)+1)}for(const row of old[table]){const key=norm(row),n=counts.get(key)??0;check(n>0,'Old row missing '+table);counts.set(key,n-1);retained++}}check(retained===572&&Object.keys(before).length===121,'Exact old retention count');
check(c(Object.keys(old))===c(Object.keys(before)),'Table set changed');for(const table of Object.keys(old)){if(!['corporate_inventory','stationary_gas','mobile_diesel','controlled_fleet','stationary_diesel','stationary_equipment','fugitive','scope1'].some(f=>table.startsWith(f+'_')))check(c(old[table])===c(before[table]),'Unrelated rows changed '+table)}for(const suffix of ['requests','audit']){const delta=['corporate_inventory','stationary_gas','mobile_diesel','controlled_fleet','stationary_diesel','stationary_equipment','fugitive','scope1'].reduce((n,f)=>n+(before[f+'_'+suffix]?.length??0)-(old[f+'_'+suffix]?.length??0),0);check(delta===37,'Exact continuation append count')}
const db=new (HostedWorkspaceDatabase as any)(runtime,'icockcoguyadhryzydvl') as HostedWorkspaceDatabase,origin='http://127.0.0.1:47821',route=createM78Routes({database:db,origin,authorities:m78FixtureAuthorities(),policy:M78_REVIEWED_POLICY,validateUser:async()=>({id:user,email:null,phone:null,fullName:null})});let gets=0,downloads=0;const get=async(path:string)=>{gets++;const r=await route(new Request(origin+'/workspace/'+company+path,{headers:{authorization:'Bearer local-review-only'}}));check(r.status===200&&r.headers.get('cache-control')?.includes('no-store'),'Member GET failed');return r};const final=await decodeScope1Register(await(await get('/scope1-inventory')).json(),company);check(c(final)===c(terminal.final),'Current decoded register differs');check(c(final.inventory.versions[0])===c(baseline.baseline.inventory.versions[0]),'Original committed inventory1 changed');check(final.process.versions.length===1&&final.inventory.versions.length===2&&final.process.reports.length===2&&final.inventory.reports.length===3,'Exact history');const totals=final.reconciliation.totals!;check(final.reconciliation.status==='reconciled_bounded_synthetic'&&totals.company.kgCo2eExact==='126850.17632025'&&totals.company.kgCo2eDisplay==='126850.1763','Gross exact');const decimal=(s:string)=>{check(/^\d+(\.\d+)?$/.test(s),'Positive decimal');const[a,b='']=s.split('.');check(b.length<=20,'Decimal scale');return BigInt(a!)*10n**20n+BigInt(b.padEnd(20,'0'))};for(const group of[totals.gasLines,totals.sourceRows,totals.facilityRows,totals.entityRows])check(group.reduce((n,r)=>n+decimal(r.kgCo2eExact),0n)===decimal(totals.company.kgCo2eExact),'Independent gross rollup');check(totals.sourceRows.length===10&&totals.facilityRows.length===2&&totals.entityRows.length===1&&totals.gasLines.length===6,'Gross dimensions');
const cov=final.coverageVersion;check(cov.version===9,'Current corporate9');for(const s of final.proof.sourceVersions)check(s.version.activity.binding.coverageVersionId===cov.id&&s.version.review?.decision==='accepted_bounded_internal','Current source review binding');for(const k of['fleet','stationary','fugitive']as const)check((final.proof[k].version?.activity as any).coverageVersionId===cov.id&&final.proof[k].review?.decision==='accepted_bounded_reconciliation','Current discovery');check(final.process.versions[0]!.review?.decision==='accepted_bounded_process_screen'&&final.inventory.versions[1]!.review?.decision==='accepted_bounded_inventory','Final reviews');
const reports:any[]=[];for(const family of['process','inventory']as const)for(const meta of final[family].reports){const base='/'+(family==='process'?'process-screen':'scope1-inventory')+'/'+meta.streamId+'/reports/'+meta.id,report=await decodeScope1Report(await(await get(base)).json(),company),snapshot=JSON.parse(report.snapshotJson);for(const[op,expected]of[['download',report.html],['snapshot',report.snapshotJson]]){const b=new Uint8Array(await(await get(base+'/'+op)).arrayBuffer());check(sha(b)===sha(expected!),'Exact report bytes');downloads++}reports.push({id:report.id,family:report.family,versionId:report.versionId,reviewId:snapshot.review?.id??null,htmlSha256:sha(report.html),snapshotSha256:sha(report.snapshotJson)})}check(reports.filter(r=>r.reviewId===null).length===3&&reports.filter(r=>r.reviewId!==null).length===2,'Captured null/accepted reports');
const after=await rows();check(c(before)===c(after),'Review changed current rows');check(sha(await readFile('.superpowers/m78-hosted-journey.jsonl'))==='d3301eb226c0cae4428c1e20cde4e2afdcf572b622e96d690cc8c262d6e44058','Old failed journal changed');const result={status:'m78_independent_exact_continuation_native_passed',createdAt:new Date().toISOString(),reviewerId:'/root/resume_recipe',database:name,journalSha256:sha(bytes),terminalSha256:prev,events:113,successfulApplicationPosts:37,verifiedApplicationPosts:37,retainedOldRows:retained,tableCount:121,currentRowsSha256:sha(c(after)),independentMemberGets:gets,exactDownloads:downloads,gross:totals.company,gasLines:6,sources:10,facilities:2,entities:1,processVersions:1,inventoryVersions:2,reports,capturedNullReviews:3,currentBindingsAndReviewsVerified:true,noReviewMutationVerified:true,sourcePinsVerified:122,oldFailedJournalPreserved:true,hostedCalls:false,providerSessions:false,scope1ReleaseReadiness:'incomplete'};await writeFile('evaluations/research-qa/m78-continuation-actual-independent-acceptance.json',JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({...result,reports:reports.length}))
}finally{await runtime.close();await admin.close()}
